import * as React from "react"
import Svg, {
  SvgProps,
  Path,
  Defs,
  Pattern,
  Use,
  Image,
} from "react-native-svg"
const AlBilad = (props: SvgProps) => (
  <Svg
   {...props}
    width={props.width || 72}
    height={props.height || 72}
    fill="none"
    viewBox="0 0 72 72"
    preserveAspectRatio="xMidYMid meet"
  >
    <Path fill="url(#a)" d="M0 0h72v72H0z" />
    <Defs>
      <Pattern
        id="a"
        width={1}
        height={1}
        patternContentUnits="objectBoundingBox"
      >
        <Use
          xlinkHref="#b"
          transform="matrix(.00455 0 0 .00455 -1.933 -1.832)"
        />
      </Pattern>
      <Image
        xlinkHref="data:image/png;base64,"
        id="b"
        width={732}
        height={1024}
        preserveAspectRatio="xMidYMid meet"
      />
    </Defs>
  </Svg>
)
export default AlBilad